fn is_ascii_digit(c: char) -> bool {
    // Returns true iff c is between '0' and '9', inclusive.
    c >= '0' && c <= '9'
}

fn all_digits(s: String) -> bool {
    // Checks that every character in s is an ASCII digit.
    // The empty string returns true.
    // We use chars().enumerate() to iterate over each character with index.
    let mut i = 0;
    let len = s.chars().count();
    // Use an explicit loop with an invariant style reasoning:
    while i < len {
        // unwrap is safe here because i < len
        if !is_ascii_digit(s.chars().nth(i).unwrap()) {
            return false;
        }
        i += 1;
    }
    true
}